    # Find the repeated row that encodes the ordered palette.
    sequence = None
    for r in range(h - 1):
        if grid[r] == grid[r + 1]:
            values = [v for v in grid[r] if v != 0]
            if len(values) >= 2:
                sequence = values
                break
    if sequence is None:
        return grid

    # Identify the main color-1 shape using diagonal as well as orthogonal
    # connectivity; some parts of the silhouette touch only diagonally.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] == 1 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append(cells)

    motif = max(components, key=len)
    top = min(r for r, c in motif)
    left = min(c for r, c in motif)
    height = max(r for r, c in motif) - top + 1
    shape = {(r - top, c - left) for r, c in motif}

    start = top - sequence.index(1) * height
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(sequence):
        for dy, dx in shape:
            y, x = start + i * height + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
